import React from "react";
import { X } from "lucide-react";
import { COLORS } from "../constants/theme";

const LINKS = ["Rings", "Necklaces", "Earrings"];

export default function MobileDrawer({ menuOpen, setMenuOpen, scrollTo, width = 280 }) {
  const handleNav = (id) => {
    scrollTo(id);
    setMenuOpen(false);
  };

  const linkStyle = {
    display: "block",
    width: "100%",
    textAlign: "left",
    padding: "14px 0",
    background: "none",
    border: "none",
    borderBottom: `1px solid ${COLORS.border}`,
    fontSize: 16,
    color: COLORS.text,
  };

  return (
    <nav
      className="md:hidden"
      aria-hidden={!menuOpen}
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        width,
        height: "100vh",
        background: COLORS.surfaceBase,
        zIndex: 1, // sits behind the sliding page (zIndex 2) and behind the header (zIndex 50)
        overflowY: "auto",
      }}
    >
      {/* Own close button — always visible inside the drawer itself, so there's
          never a moment where the only way to close it has scrolled off-screen. */}
      <div className="flex items-center justify-between px-6" style={{ height: 64 }}>
        <span style={{ fontSize: 13, letterSpacing: "0.06em", color: COLORS.textMuted || COLORS.text, textTransform: "uppercase" }}>
          Menu
        </span>
        <button
          onClick={() => setMenuOpen(false)}
          aria-label="Close menu"
          tabIndex={menuOpen ? 0 : -1}
          style={{ background: "none", border: "none", color: COLORS.text, padding: 8 }}
        >
          <X size={20} strokeWidth={1.6} />
        </button>
      </div>

      <div className="flex flex-col px-6">
        {LINKS.map((c) => (
          <button key={c} onClick={() => handleNav("shop")} tabIndex={menuOpen ? 0 : -1} style={linkStyle}>
            {c}
          </button>
        ))}
        <button onClick={() => handleNav("craft")} tabIndex={menuOpen ? 0 : -1} style={linkStyle}>
          The Craft
        </button>
        <button onClick={() => handleNav("faq")} tabIndex={menuOpen ? 0 : -1} style={{ ...linkStyle, borderBottom: "none" }}>
          FAQ
        </button>
      </div>
    </nav>
  );
}
